{
  "name": "opencode-debate",
  "version": "3.3.1",
  "description": "Run structured multi-model debates in OpenCode.",
  "license": "MIT",
  "author": "DrTralala <drtralala@outlook.com>",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/DrTralala/opencode-debate.git"
  },
  "bugs": {
    "url": "https://github.com/DrTralala/opencode-debate/issues"
  },
  "homepage": "https://github.com/DrTralala/opencode-debate#readme",
  "keywords": [
    "opencode",
    "plugin",
    "debate",
    "llm",
    "multi-agent"
  ],
  "files": [
    "config.yaml",
    "index.ts",
    "src/",
    "src/transcript-persistence.ts",
    "scripts/format_response.py",
    "scripts/generate_html.py",
    "scripts/publish_transcript.py",
    "scripts/render_markdown.mjs"
  ],
  "publishConfig": {
    "access": "public"
  },
  "type": "module",
  "main": "./index.ts",
  "engines": {
    "node": ">=24.15.0"
  },
  "scripts": {
    "test": "node --test tests/*.test.ts tests/*.test.mjs",
    "typecheck": "tsc --noEmit",
    "pack:check": "node scripts/check_package.mjs"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.17.13",
    "@opencode-ai/sdk": ">=1.17.13"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "1.17.13",
    "@opencode-ai/sdk": "1.17.13",
    "@types/node": "^24.13.3",
    "typescript": "^5.9.0"
  },
  "dependencies": {
    "marked": "18.0.7",
    "sanitize-html": "2.17.6",
    "yaml": "2.9.0"
  }
}
